const d={"t": "Game", "y": "FILE 04", "d": "游戏项目、交互原型与体验笔记。项目、试玩地址和游戏截图待归档。", "bg": "#282e3b", "ink": "#e5dfc8", "big": ["GAME"]}; export default {name:d.t,fill:false,cassette:{shell:'orange-black',drawLabel(g,w,h){g.fillStyle='#17181b';g.fillRect(0,0,w,h);g.save();g.beginPath();g.rect(0,0,w,h);g.clip();g.strokeStyle='#ee7927';g.lineWidth=h*.27;for(let x=-h;x<w+h;x+=h*.65){g.beginPath();g.moveTo(x,0);g.lineTo(x+h,h);g.stroke()}g.restore();g.fillStyle='#17181b';g.fillRect(w*.035,h*.17,w*.75,h*.66);g.fillStyle='#f3a246';g.font='850 '+h*.4+'px "Noto Sans SC",sans-serif';g.fillText(d.t,w*.055,h*.66);g.font=h*.15+'px monospace';g.textAlign='right';g.fillText(d.y,w*.96,h*.66);g.textAlign='left';}},mount({ctx:g,width:w,height:h}){return {frame(t){g.fillStyle=d.bg;g.fillRect(0,0,w,h);g.strokeStyle='#b18f7366';g.strokeRect(65,65,w-130,h-130);g.fillStyle=d.ink;g.font='24px monospace';g.fillText('PRIVATE COLLECTION / '+d.y,95,120);g.font='600 70px serif';g.fillText(d.t,95,280);g.font='23px sans-serif';let text=d.d, y=360;while(text.length){g.fillText(text.slice(0,27),95,y);text=text.slice(27);y+=42}g.font='20px monospace';g.fillText('PLAY  >  PERSONAL ARCHIVE',95,h-110)},stop(){},input(){}}}};